"""Application port interface and typed output schemas for AI executive analytics."""

from __future__ import annotations

from typing import Protocol

from pydantic import BaseModel, Field

from src.indicators.domain.models import CostCenterIndicator
from src.indicators.domain.services.simulator import CostCenterImpact
from src.intelligence.domain.models import AllocationAnomaly
from src.shared.domain.value_objects import Period, SupportedLanguage


class ExecutiveSummaryResponse(BaseModel):
    """Structured executive report generated by AI intelligence layer."""

    executive_summary: str = Field(
        description="High-level narrative executive summary of period performance."
    )
    financial_health_status: str = Field(
        description=(
            "Overall organizational budget health: HEALTHY, CONCERNING, or CRITICAL."
        )
    )
    root_causes: list[str] = Field(
        description=(
            "Key contracts, departments, or allocation shifts driving deviations."
        )
    )
    strategic_recommendations: list[str] = Field(
        description=(
            "Actionable executive steps for financial control and risk mitigation."
        )
    )


class ScenarioEvaluationResponse(BaseModel):
    """Structured appraisal of a what-if simulation generated by AI."""

    scenario_name: str = Field(description="Name of the evaluated scenario.")
    strategic_feasibility: str = Field(
        description="Feasibility level: HIGH, MODERATE, LOW, or UNACCEPTABLE."
    )
    key_tradeoffs: list[str] = Field(
        description=(
            "Key budgetary and operational trade-offs identified in simulation."
        )
    )
    recommendations: list[str] = Field(
        description=(
            "Strategic executive guidance and recommended actions for this scenario."
        )
    )


class AIPort(Protocol):
    """Application port abstraction for AI model operations."""

    async def generate_executive_summary(
        self,
        indicators: list[CostCenterIndicator],
        anomalies: list[AllocationAnomaly],
        period: Period,
        language: SupportedLanguage = SupportedLanguage.PT_BR,
    ) -> ExecutiveSummaryResponse:
        """Synthesize period metrics and anomalies into an executive summary.

        Args:
            indicators: Calculated performance indicators.
            anomalies: Detected allocation anomalies.
            period: The target fiscal period.
            language: Requested language for the summary (default: pt-br).

        Returns:
            ExecutiveSummaryResponse: Validated executive report.
        """
        ...

    async def evaluate_scenario(
        self,
        scenario_name: str,
        impacts: list[CostCenterImpact],
        period: Period,
    ) -> ScenarioEvaluationResponse:
        """Evaluate strategic implications of a what-if simulation.

        Args:
            scenario_name: Name of the scenario.
            impacts: Differential impacts across cost centers.
            period: The evaluated period.

        Returns:
            ScenarioEvaluationResponse: Strategic feasibility analysis.
        """
        ...
